import type { HTMLArkProps } from '@ark-ui/react/factory';
import { ark } from '@ark-ui/react/factory';
import { clsx } from 'clsx';
import { forwardRef } from 'react';
import styles from './Separator.module.css';

type SeparatorOrientation = 'horizontal' | 'vertical';
type SeparatorSize = 'xs' | 'sm' | 'md' | 'lg';
type SeparatorVariant = 'solid' | 'dashed' | 'dotted';

type SeparatorRootProps = HTMLArkProps<'span'> & {
  orientation?: SeparatorOrientation;
  size?: SeparatorSize;
  variant?: SeparatorVariant;
};

const Separator = forwardRef<HTMLSpanElement, SeparatorRootProps>(function Separator(
  {
    className,
    orientation = 'horizontal',
    role,
    size = 'sm',
    variant = 'solid',
    'aria-orientation': _ariaOrientation,
    ...props
  },
  ref,
) {
  const resolvedRole = role ?? 'separator';

  return (
    <ark.span
      {...props}
      ref={ref}
      role={resolvedRole}
      aria-orientation={resolvedRole === 'separator' ? orientation : undefined}
      data-scope="separator"
      data-part="root"
      data-slot="separator-root"
      data-orientation={orientation}
      data-size={size}
      data-variant={variant}
      className={clsx(styles.root, className)}
    />
  );
});

export { Separator };
export type { SeparatorOrientation, SeparatorRootProps, SeparatorSize, SeparatorVariant };

@layer moduix.components {
  .root {
    --_separator-thickness: var(--moduix-border-width-sm);

    display: block;
    flex-shrink: 0;
    margin: 0;
    border: 0 solid var(--moduix-separator-color, var(--moduix-color-border));

    &[data-size='xs'] {
      --_separator-thickness: 0.5px;
    }

    &[data-size='md'] {
      --_separator-thickness: var(--moduix-border-width-md);
    }

    &[data-size='lg'] {
      --_separator-thickness: 3px;
    }

    &[data-variant='dashed'] {
      border-style: dashed;
    }

    &[data-variant='dotted'] {
      border-style: dotted;
    }

    &[data-orientation='horizontal'] {
      width: 100%;
      height: 0;
      border-block-start-width: var(--moduix-separator-thickness, var(--_separator-thickness));
    }

    &[data-orientation='vertical'] {
      width: 0;
      height: 1em;
      border-inline-start-width: var(--moduix-separator-thickness, var(--_separator-thickness));
    }
  }
}
